import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { HttpError } from '../../api/http';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { listPeriods, periodOf, periodsKey } from '../periods/api';
import { claimDue, showDue, type GradeOn, type Late, type Rate } from '../rates/api';
import { addClaim, claimsKey, dueBy, isOverdue, moveClaim, updateClaim, type Claim, type ClaimAction, type ClaimInput } from './api';

const EMPTY: ClaimInput = { amount: '', date: '', note: '', corrects: '' };

const LABELS: Record<ClaimAction, string> = { open: 'Open', settle: 'Settle', void: 'Void', approve: 'Approve', reject: 'Reject' };
const DONE: Record<ClaimAction, string> = { open: 'opened', settle: 'settled', void: 'voided', approve: 'approved', reject: 'rejected' };

/** A person's claims: a form that adds a claim or edits one, and the claims newest first, each
 *  with its status, its due (fixed when settled, else at the rate in force on the claim's date of the
 *  person's grade in force then (`gradeOn`) and at least the sheet's `floor`, or bound by the person's last statement; none when
 *  there is no such rate; an overdue one gains its late charge on top, see `charges`), its due-by (its date plus the sheet's `terms` in days) and whether it is
 *  overdue (OPEN and due-by before the sheet's `today`), whether
 *  it is stated,
 *  the period its date falls in (none when no period contains it), who opened it, and buttons that
 *  change its status (the user who opened a claim cannot settle it; a clerk settling one whose due is
 *  above the sheet's clerk limit makes it PENDING, which a steward other than its opener approves,
 *  or any steward rejects with a reason typed beside it), a checkbox that selects it for a bulk action, and for a correction (a negative amount, no floor and no late
 *  charge) the number of the SETTLED claim it corrects. Only a DRAFT can be edited:
 *  editing any other claim is refused with an error on the claim. */
export function PersonClaims({ sheetId, user, personId, claims, gradeOn, rates, floor, terms, today, charges, selected, onSelect }: {
  sheetId: string; user: string; personId: number; claims: Claim[]; gradeOn: GradeOn; rates: Rate[] | undefined;
  floor: string; terms: number; today: string; charges: Late;
  /** The claims selected for a bulk action, and how one is selected or unselected. */
  selected: ReadonlySet<number>; onSelect: (id: number, on: boolean) => void;
}) {
  const queryClient = useQueryClient();
  const periods = useQuery({ queryKey: periodsKey(sheetId), queryFn: () => listPeriods(sheetId) });
  const [form, setForm] = useState<ClaimInput>(EMPTY);
  const [editing, setEditing] = useState<number | null>(null);
  // The claim whose edit was refused (it is not a DRAFT); cleared by the next action on any claim here.
  const [editRefused, setEditRefused] = useState<number | null>(null);
  // The rejection reason typed for each claim.
  const [reasons, setReasons] = useState<Record<number, string>>({});

  const save = useMutation({
    mutationFn: (v: { id: number | null; input: ClaimInput }) =>
      v.id === null ? addClaim(sheetId, user, personId, v.input) : updateClaim(sheetId, user, v.id, v.input),
    onSuccess: () => {
      setForm(EMPTY);
      setEditing(null);
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  const submitOnce = useSubmitOnce();
  const actOnce = useSubmitOnce();

  // The claim whose last status change was refused; cleared by the next action on any claim here.
  const move = useMutation({
    mutationFn: (v: { id: number; action: ClaimAction }) =>
      moveClaim(sheetId, user, v.id, v.action, reasons[v.id] ?? ''),
    onSuccess: (_, v) => {
      if (v.action === 'reject') setReasons((r) => ({ ...r, [v.id]: '' }));
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
  });

  const act = (id: number, action: ClaimAction) => {
    actOnce(() => {
      move.reset();
      setEditRefused(null);
      return move.mutateAsync({ id, action });
    });
  };

  const change = (patch: Partial<ClaimInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  const open = (c: Claim) => {
    move.reset();
    if (c.status !== 'DRAFT') {
      setEditRefused(c.id);
      return;
    }
    setEditRefused(null);
    setForm({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '' });
    setEditing(c.id);
    save.reset();
  };

  const cancel = () => {
    setForm(EMPTY);
    setEditing(null);
    save.reset();
  };

  return (
    <div>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const v = { id: editing, input: form };
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(v);
          });
        }}
      >
        <input data-testid="claim-form-amount" placeholder="Amount" value={form.amount}
          onChange={(e) => change({ amount: e.target.value })} />{' '}
        <input type="date" data-testid="claim-form-date" value={form.date}
          onChange={(e) => change({ date: e.target.value })} />{' '}
        <input data-testid="claim-form-note" placeholder="Note" value={form.note}
          onChange={(e) => change({ note: e.target.value })} />{' '}
        <input data-testid="claim-form-corrects" placeholder="Corrects no." value={form.corrects}
          onChange={(e) => change({ corrects: e.target.value })} />{' '}
        <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
          {editing === null ? 'Add claim' : 'Save claim'}
        </button>
        {save.isError && (
          <span data-testid="claim-form-error">{save.error instanceof HttpError && save.error.status === 423
            ? 'A claim dated inside a closed period cannot be added or edited.'
            : save.error instanceof HttpError && save.error.status === 409
            ? 'Only a DRAFT claim can be edited.'
            : 'A claim needs an amount with up to two decimals; a negative one (a correction) must name, by number, a SETTLED claim of this person.'}</span>
        )}
      </form>
      <table>
        <tbody>
          {claims.map((c) => (
            <tr key={c.id} data-testid={`claim-row-${c.id}`}>
              <td>
                <input type="checkbox" data-testid="claim-select" checked={selected.has(c.id)}
                  onChange={(e) => onSelect(c.id, e.target.checked)} />
              </td>
              <td data-testid="claim-number">{c.number ?? ''}</td>
              <td data-testid="claim-amount">{Number(c.amount).toFixed(2)}</td>
              <td data-testid="claim-date">{c.date}</td>
              <td data-testid="claim-note">{c.note}</td>
              <td data-testid="claim-corrects">{c.corrects ?? ''}</td>
              <td data-testid="claim-due">{showDue(claimDue(c, rates, gradeOn, floor, charges))}</td>
              <td>
                Due by <span data-testid="claim-due-by">{dueBy(c, terms)}</span>{' '}
                overdue <span data-testid="claim-overdue">{isOverdue(c, terms, today) ? 'yes' : 'no'}</span>
              </td>
              <td data-testid="claim-status">{c.status}</td>
              <td data-testid="claim-opened-by">{c.openedBy ?? ''}</td>
              <td>
                Stated <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>
              </td>
              <td data-testid="claim-period">{periodOf(periods.data, c.date)?.name ?? ''}</td>
              <td>
                {(['open', 'settle', 'void', 'approve'] as const).map((a) => (
                  <button key={a} type="button" data-testid={`claim-${a}`} disabled={move.isPending}
                    onClick={() => act(c.id, a)}>
                    {LABELS[a]}
                  </button>
                ))}{' '}
                <input data-testid="claim-reject-reason" placeholder="Reason" value={reasons[c.id] ?? ''}
                  onChange={(e) => {
                    setReasons((r) => ({ ...r, [c.id]: e.target.value }));
                    if (move.variables?.id === c.id) move.reset();
                  }} />{' '}
                <button type="button" data-testid="claim-reject" disabled={move.isPending}
                  onClick={() => act(c.id, 'reject')}>
                  {LABELS.reject}
                </button>{' '}
                <button type="button" data-testid="claim-edit" onClick={() => open(c)}>
                  Edit
                </button>
                {editing === c.id && (
                  <button type="button" data-testid="claim-cancel" onClick={cancel}>
                    Cancel
                  </button>
                )}
                {editRefused === c.id && (
                  <span data-testid="claim-error">
                    {`A ${c.status} claim cannot be edited. To change it, void it and add a new one.`}
                  </span>
                )}
                {move.isError && move.variables?.id === c.id && (
                  <span data-testid="claim-error">{move.error instanceof HttpError && move.error.status === 423
                    ? 'A claim dated inside a closed period cannot be changed.'
                    : move.error instanceof HttpError && move.error.status === 400
                    ? 'A rejection needs a reason.'
                    : c.status === 'OPEN' && move.variables.action === 'settle'
                    ? 'The user who opened a claim cannot settle it.'
                    : c.status === 'PENDING' && move.variables.action === 'approve'
                    ? 'Only a steward who did not open a claim can approve it.'
                    : c.status === 'PENDING' && move.variables.action === 'reject'
                    ? 'Only a steward can reject a claim.'
                    : `A ${c.status} claim cannot be ${DONE[move.variables.action]}.`}</span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
import { getJson, postJson, putJson } from '../../api/http';
import { sheetKey } from '../sheet/api';

/** A claim's status: DRAFT, opened to OPEN, settled to SETTLED (or, by a clerk above the clerk limit,
 *  to PENDING, which a steward approves to SETTLED or rejects back to OPEN); a DRAFT, OPEN or PENDING
 *  claim can be voided. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
/** A change of a claim's status. */
export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export const isOpen = (c: Pick<Claim, 'status'>) => c.status === 'OPEN' || c.status === 'PENDING';

/** Whether a statement's figure binds a claim now: it was bound to one and is not PENDING (a PENDING
 *  claim shows and totals its live figure until it is rejected). */
export const isBound = (c: Claim) => c.stated && c.statedDue !== null && c.status !== 'PENDING';

/** A claim: its amount as two-decimal text, its date (yyyy-MM-dd), its note, its status and its
 *  number on the sheet (given when opened: the sheet-wide 1, 2, ... or, under period numbering,
 *  <period>-<n> or X-<n>; null while a draft), and its settled due
 *  (fixed when settled; null otherwise, or when there was no rate then — its due stays live), and who
 *  opened it (null while a draft; that user cannot settle it), and whether its person's last statement
 *  bound it, with the figure it bound (null when it had none): a bound claim shows and totals that.
 *  A correction (a negative amount) has the number of the SETTLED claim it corrects (null otherwise).
 *  `roundDate` is the date its live figures round by: its own, or a correction's claim's it corrects. */
export type Claim = {
  id: number; sheetId: string; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  number: string | null; settledDue: string | null; openedBy: string | null;
  stated: boolean; statedDue: string | null; corrects: string | null; roundDate: string;
};
/** `corrects`: the number of the SETTLED claim of the same person a correction (a negative amount) corrects. */
export type ClaimInput = { amount: string; date: string; note: string; corrects: string };

/** Whether a claim is a correction: its amount is negative. */
export const isCorrection = (c: Pick<Claim, 'amount'>) => c.amount.trim().startsWith('-') && Number(c.amount) !== 0;

const sheetBase = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function listClaims(sheetId: string): Promise<Claim[]> {
  return getJson<Claim[]>(`${sheetBase(sheetId)}/claims`);
}

/** Add a claim to a person; refused (rejects) when the amount is missing or has more than two
 *  decimals, the date is not a date, or it is a correction (negative) that does not name by number a
 *  SETTLED claim of the person. A blank date takes the sheet's today. */
export function addClaim(sheetId: string, by: string, personId: number, input: ClaimInput): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/people/${personId}/claims?by=${encodeURIComponent(by)}`, input);
}

/** Edit a claim; refused (rejects) like an add. */
export function updateClaim(sheetId: string, by: string, id: number, input: ClaimInput): Promise<Claim> {
  return putJson<Claim>(`${sheetBase(sheetId)}/claims/${id}?by=${encodeURIComponent(by)}`, input);
}

/** Change a claim's status; refused (rejects) when its status does not allow the change, when the
 *  user settling or approving it is the one who opened it, when a non-steward approves or rejects it,
 *  or when a rejection has no `reason`. */
export function moveClaim(sheetId: string, by: string, id: number, action: ClaimAction, reason = ''): Promise<Claim> {
  const extra = action === 'reject' ? `&reason=${encodeURIComponent(reason)}` : '';
  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/${action}?by=${encodeURIComponent(by)}${extra}`, {});
}

/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED do. */
export const counts = (c: Claim) => isOpen(c) || c.status === 'SETTLED';

/** The claims that count in live totals: all but the open claims of people on hold (their SETTLED
 *  claims still count). */
export function liveClaims(claims: Claim[], people: Array<{ id: number; held: boolean }> | undefined): Claim[] {
  const held = new Set((people ?? []).filter((p) => p.held).map((p) => p.id));
  return claims.filter((c) => !(isOpen(c) && held.has(c.personId)));
}

/** Sum the amounts of the claims that count (see `counts`) exactly (in cents), shown with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((t, c) => t + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** A claim's due-by (yyyy-MM-dd): its date plus the sheet's terms in days. */
export function dueBy(c: Claim, terms: number): string {
  const d = new Date(`${c.date}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + terms);
  return d.toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is open (OPEN or PENDING) and its due-by is before the sheet's `today`. */
export const isOverdue = (c: Claim, terms: number, today: string) =>
  isOpen(c) && today !== '' && dueBy(c, terms) < today;

/** How many of the selected claims a bulk open opened, and how many it refused (left as they were). */
export type BulkOpenResult = { opened: number; refused: number };

/** Open the selected claims together, numbered in list order (people in added order, newest claim
 *  first within a person); each that cannot be opened is left as it is and counted as refused. */
export function bulkOpenClaims(sheetId: string, by: string, claimIds: number[]): Promise<BulkOpenResult> {
  return postJson<BulkOpenResult>(`${sheetBase(sheetId)}/bulk-open?by=${encodeURIComponent(by)}`, { claimIds });
}

